    return np.append(scores, new_bin_score)

def priority_fn_v1(item_size, open_bin_remaining_capacities, capacity):
    """Improved Best-Fit heuristic incorporating tight-packing bias and avoidance of awkward residues."""
    rem = np.asarray(open_bin_remaining_capacities, dtype=float)
    if rem.size == 0:
        return np.array([0.0])

    gaps = rem - item_size
    # Exact fit is ideal; very small gaps leave little room for future items unless 0
    # Reward filling a bin completely or leaving usable space while penalising creating tiny awkward gaps (e.g. 1-3)
    scores = -gaps
    scores = np.where(gaps == 0, scores + capacity, scores)
    scores = np.where((gaps > 0) & (gaps < 5), scores - 5.0, scores)

    new_bin_score = -capacity - 1.0
    return np.append(scores, new_bin_score)
